window.BANKS = window.BANKS || {};
window.BANKS.nvidia = {
  code: "NCA-AIIO",
  name: "NVIDIA-Certified Associate: AI Infrastructure and Operations",
  facts: [
    ["Questions", "50, multiple choice"],
    ["Time", "60 minutes"],
    ["Pass mark", "Not published (plan for 70%+)"],
    ["Price", "$125, online proctored (Certiverse)"],
    ["Valid", "2 years"]
  ],
  pace: "72 seconds per question. First pass: answer everything, flag doubts, then return.",
  domains: [
    { id: 1, name: "Essential AI Knowledge", w: 38 },
    { id: 2, name: "AI Infrastructure", w: 40 },
    { id: 3, name: "AI Operations", w: 22 }
  ],
  mock: { count: 50, minutes: 60, per: [19, 20, 11] },
  plan: [
    ["Day 1", "Domain 1 part A: AI vs ML vs DL, why AI exploded, CPU vs GPU, GPU generations and precisions. Do Practice D1 Q1–19."],
    ["Day 2", "Domain 1 part B: NVIDIA software stack and industry SDKs, training vs inference. Practice D1 Q20–38."],
    ["Day 3", "Domain 2 part A: NVLink/NVSwitch, InfiniBand vs RoCE, GPUDirect, DPU, DGX/HGX/SuperPOD. Practice D2 Q1–20."],
    ["Day 4", "Domain 2 part B: four networks, topologies, power, PUE, cooling, on-prem vs cloud, storage. Practice D2 Q21–40."],
    ["Day 5", "Domain 3: nvidia-smi, DCGM, XID/ECC, Slurm vs Kubernetes, GPU Operator, Run:ai, MIG vs vGPU vs time-slicing. Practice all D3."],
    ["Day 6", "Mock exam 1 under timer. Review every wrong and flagged answer. Re-read the matching memory hooks."],
    ["Day 7", "Retry missed questions, Mock exam 2. Book the exam when you score 85%+ twice in a row."]
  ],
  modules: [
    {
      d: 1, title: "Essential AI Knowledge", topics: [
        { h: "AI, ML, DL, GenAI", pts: [
          "<b>AI</b> = machines doing tasks that need human-like intelligence.",
          "<b>ML</b> = subset of AI that learns patterns from data instead of hand-written rules.",
          "<b>DL</b> = subset of ML using multi-layer neural networks that learn features themselves (edges → shapes → objects).",
          "<b>Generative AI</b> = DL models that create new content (text, images, code). LLMs are transformers.",
          "Learning types: supervised (labels), unsupervised (no labels, clustering), reinforcement (rewards)."
        ], hook: "Russian dolls: AI ⊃ ML ⊃ DL ⊃ GenAI." },
        { h: "Why AI took off", pts: [
          "<b>Data</b>: internet-scale datasets.",
          "<b>Compute</b>: GPUs and accelerated computing made training feasible.",
          "<b>Algorithms</b>: deep nets, then transformers (2017) that parallelize well.",
          "Plus mature frameworks (PyTorch, TensorFlow) and pretrained models."
        ], hook: "D-C-A: Data, Compute, Algorithms." },
        { h: "CPU vs GPU", pts: [
          "CPU: few powerful cores, big caches, branch prediction, low latency for serial and branchy code, runs the OS.",
          "GPU: thousands of simpler cores (SIMT), high-bandwidth memory (HBM), built for throughput on parallel math.",
          "Accelerated computing = offload the parallel part to the GPU, keep serial logic on the CPU.",
          "Least benefit from GPU: single-threaded, branch-heavy business logic."
        ], hook: "CPU is a sports car with 2 seats; GPU is a fleet of buses. Both reach the city; the buses move more people." },
        { h: "GPU generations and precision", pts: [
          "<b>Volta</b> V100 (2017): first Tensor Cores.",
          "<b>Ampere</b> A100 (2020): TF32, <b>MIG</b> (up to 7 instances), 3rd-gen NVLink.",
          "<b>Hopper</b> H100/H200 (2022): <b>Transformer Engine with FP8</b>, NVLink 4 (900 GB/s per GPU).",
          "<b>Blackwell</b> B200/GB200 (2024): 2nd-gen Transformer Engine with <b>FP4</b>, NVLink 5 (1.8 TB/s per GPU).",
          "<b>Grace</b> = NVIDIA Arm CPU. Grace Hopper / Grace Blackwell superchips link CPU and GPU with NVLink-C2C (900 GB/s).",
          "Tensor Cores = matrix multiply-accumulate units. Mixed precision = compute in FP16/BF16, keep master weights in FP32."
        ], hook: "Very Awesome Hackers Build: Volta → Ampere → Hopper → Blackwell. Precision ladder going down the bits: FP32 → TF32 → FP16/BF16 → FP8 (Hopper) → FP4 (Blackwell)." },
        { h: "Training vs inference", pts: [
          "Training: huge compute, large memory, fast GPU-to-GPU links, runs for days, throughput matters.",
          "Inference: many requests, latency SLAs, cost and performance per watt matter, scale out, can run at the edge.",
          "Data parallelism: copy the model to every GPU, split the batch, sync gradients with all-reduce (NCCL).",
          "Model parallelism (tensor, pipeline): split the model when it does not fit in one GPU.",
          "Inference tricks: quantization (INT8/FP8/FP4), batching (throughput up, latency up), TensorRT compilation."
        ], hook: "Training is the gym (heavy, long, together). Inference is the match day (fast, many, everywhere)." },
        { h: "NVIDIA software stack", pts: [
          "Layers: GPU → driver → <b>CUDA</b> → libraries (cuDNN, cuBLAS, NCCL) → frameworks (PyTorch, TensorFlow) → <b>NGC</b> containers → <b>NVIDIA AI Enterprise</b> (licensed, supported).",
          "<b>cuDNN</b>: deep learning primitives. <b>NCCL</b>: multi-GPU collectives (all-reduce).",
          "<b>DALI</b>: GPU data loading and augmentation. <b>RAPIDS</b>: GPU pandas (cuDF) and scikit-learn (cuML), Spark acceleration.",
          "<b>NeMo</b>: build, customize and guard generative AI and LLMs.",
          "<b>TensorRT</b> / TensorRT-LLM: optimize models for inference (fusion, quantization).",
          "<b>Triton Inference Server</b>: serve models from any framework, dynamic batching, concurrent models.",
          "<b>NIM</b>: prebuilt optimized inference microservices with standard APIs.",
          "<b>NGC</b>: catalog of GPU-optimized containers, models, Helm charts."
        ], hook: "Lifecycle path: Prepare (RAPIDS, DALI) → Train (PyTorch, NeMo, NCCL) → Optimize (TensorRT) → Serve (Triton, NIM) → Monitor (DCGM)." },
        { h: "Industry platforms", pts: [
          "<b>Clara</b>: healthcare, imaging, genomics. <b>Metropolis</b> + DeepStream: video analytics, smart cities.",
          "<b>Riva</b>: speech AI (ASR, TTS). <b>Merlin</b>: recommender systems. <b>Morpheus</b>: AI cybersecurity.",
          "<b>Isaac</b>: robotics. <b>DRIVE</b>: autonomous vehicles. <b>Omniverse</b>: digital twins on OpenUSD.",
          "<b>cuOpt</b>: route and logistics optimization. <b>Jetson</b>: edge AI modules. <b>IGX</b>: industrial/medical edge."
        ], hook: "Clara cares (health), Metropolis watches (video), Riva talks (speech), Merlin recommends, Morpheus defends, Isaac moves." }
      ]
    },
    {
      d: 2, title: "AI Infrastructure", topics: [
        { h: "Interconnects inside and between servers", pts: [
          "<b>PCIe</b>: CPU ↔ GPU and NICs inside a server. Slowest of the GPU links.",
          "<b>NVLink</b>: direct GPU ↔ GPU, many times PCIe bandwidth.",
          "<b>NVSwitch</b>: connects all GPUs all-to-all at full NVLink speed (inside DGX/HGX, and across a GB200 NVL72 rack).",
          "Between servers: <b>InfiniBand</b> or <b>Ethernet with RoCE</b>."
        ], hook: "Inside the box: NVLink. Between boxes: InfiniBand." },
        { h: "InfiniBand vs RoCE Ethernet", pts: [
          "InfiniBand: natively lossless (credit-based flow control), RDMA, very low latency, managed by a <b>Subnet Manager</b> (UFM).",
          "Speeds: HDR 200 Gb/s, <b>NDR 400 Gb/s</b> (Quantum-2, ConnectX-7), XDR 800 Gb/s (Quantum-X800, ConnectX-8).",
          "RoCE v2 = RDMA over Ethernet. Needs lossless tuning: <b>PFC</b> + <b>ECN</b>.",
          "<b>Spectrum-X</b>: NVIDIA Ethernet platform tuned for AI (adaptive routing, congestion control, SuperNICs)."
        ], hook: "InfiniBand is a private highway built for race cars. RoCE is the public highway with special lanes painted for them (PFC/ECN)." },
        { h: "GPUDirect family and DPUs", pts: [
          "<b>GPUDirect RDMA</b>: NIC reads/writes GPU memory directly, bypassing CPU and system RAM.",
          "<b>GPUDirect Storage</b>: storage → GPU memory direct path, no CPU bounce buffer.",
          "<b>GPUDirect P2P</b>: GPU ↔ GPU in the same server.",
          "<b>DPU (BlueField)</b>: offloads, accelerates and isolates networking, storage and security from the host CPU. Programmed with <b>DOCA</b>. Enables zero-trust because security runs outside the host.",
          "<b>ConnectX</b>: NVIDIA network adapters (HCA/SmartNIC)."
        ], hook: "CPU runs the apps, GPU runs the math, DPU runs the plumbing." },
        { h: "Systems: DGX, HGX, PODs", pts: [
          "<b>HGX</b>: GPU baseboard OEMs build servers on. <b>DGX</b>: NVIDIA complete system plus software and support.",
          "<b>DGX H100</b>: 8 GPUs, NVSwitch, 8 × 400 Gb/s compute ports, about <b>10.2 kW</b> max (DGX A100 about 6.5 kW).",
          "<b>GB200 NVL72</b>: 72 Blackwell GPUs + 36 Grace CPUs as one NVLink domain, liquid cooled, roughly 120+ kW per rack.",
          "<b>BasePOD</b>: reference architecture. <b>SuperPOD</b>: turnkey large-scale AI data center built from scalable units.",
          "<b>DGX Cloud</b>: NVIDIA AI platform in the cloud."
        ], hook: "One DGX = 8 GPUs ≈ 10 kW. Remember it as 8 and 10." },
        { h: "Cluster networks and topology", pts: [
          "Four networks: <b>compute fabric</b> (east-west GPU traffic, InfiniBand), <b>storage fabric</b>, <b>in-band management</b>, <b>out-of-band</b> management (BMC: IPMI/Redfish).",
          "East-west = server to server. North-south = in and out of the data center.",
          "<b>Non-blocking fat-tree</b>: full bisection bandwidth.",
          "<b>Rail-optimized</b>: GPU n's NIC in every server goes to the same leaf (rail), fewer hops for collectives.",
          "Poor scaling with GPUs waiting on all-reduce → fix the fabric."
        ], hook: "C-S-I-O: Compute, Storage, In-band, Out-of-band. OOB still works when the OS is dead." },
        { h: "Power, cooling, facility", pts: [
          "<b>PUE</b> = total facility power ÷ IT equipment power. 1.0 is perfect; lower is better.",
          "Air cooling tops out around 30–40 kW per rack. Above that: <b>direct-to-chip liquid</b>, rear-door heat exchangers, immersion.",
          "Hot aisle / cold aisle containment stops hot and cold air mixing.",
          "Redundancy: N+1 or 2N power supplies and dual feeds so one failure does not kill a training run.",
          "Also check floor weight loading, rack space, cabling and power circuits."
        ], hook: "PUE: Power Used Everywhere ÷ Power Used by Equipment. 1.5 MW / 1.0 MW = 1.5." },
        { h: "On-prem vs cloud vs hybrid", pts: [
          "On-prem: control, data sovereignty, cheaper at high steady utilization, but CAPEX and lead time.",
          "Cloud: elastic, fast start, OPEX, good for spiky or short projects.",
          "Hybrid: steady load on-prem, burst to cloud for peaks."
        ], hook: "Own the house if you live there every day; rent the hotel for a short trip." },
        { h: "Storage and sizing", pts: [
          "Training data: parallel file systems (Lustre, IBM Storage Scale, WEKA) for high aggregate throughput.",
          "Checkpoints create write bursts: need high write bandwidth.",
          "Scale up = more or bigger GPUs in a node (NVLink). Scale out = more nodes (InfiniBand/Ethernet).",
          "LLM pre-training: multi-node 8-GPU HGX/DGX with InfiniBand. Efficient inference/video: L4. Mixed graphics + AI: L40S. Edge: Jetson."
        ], hook: "Big brain = many DGX on InfiniBand. Small job at the edge = Jetson." }
      ]
    },
    {
      d: 3, title: "AI Operations", topics: [
        { h: "Monitoring tools", pts: [
          "<b>nvidia-smi</b>: single-node CLI (utilization, memory, temperature, power, processes, MIG).",
          "<b>DCGM</b>: data-center-scale GPU management: health, diagnostics (<code>dcgmi diag</code>), policies, telemetry.",
          "<b>DCGM Exporter → Prometheus → Grafana</b> for cluster dashboards and alerts.",
          "Triton and NIM expose inference metrics (latency, throughput, queue time) for Prometheus."
        ], hook: "smi = Single Machine Inspection. DCGM = Data Center GPU Manager." },
        { h: "Metrics and troubleshooting", pts: [
          "Watch: GPU utilization, memory used, temperature, power, clocks and throttle reasons, ECC errors, XID errors, NVLink/PCIe throughput.",
          "<b>XID</b> errors = driver-reported GPU faults (XID 79 = fell off the bus, XID 48 = double-bit ECC).",
          "Single-bit ECC = corrected. Double-bit (uncorrectable) ECC = drain node, diagnose, RMA.",
          "Low GPU utilization with CPU pegged = data pipeline bottleneck (fix with DALI, more loaders, faster storage, GPUDirect Storage).",
          "Clocks dropping with thermal reason = cooling problem."
        ], hook: "ECC and XID are the GPU's check-engine lights." },
        { h: "Orchestration and scheduling", pts: [
          "<b>Slurm</b>: HPC batch scheduler (sbatch, srun, GRES for GPUs). Default on DGX SuperPOD.",
          "<b>Kubernetes</b>: containers. <b>GPU Operator</b> installs driver, container toolkit, device plugin (<code>nvidia.com/gpu</code>), DCGM exporter, MIG manager.",
          "<b>NVIDIA Container Toolkit</b> lets Docker/containerd containers use GPUs.",
          "<b>Run:ai</b>: GPU pooling, fractional GPUs, team quotas, fair share on Kubernetes.",
          "<b>Base Command Manager</b>: provision and manage cluster nodes, sets up Slurm or Kubernetes.",
          "Gang scheduling: start all workers of a distributed job together. Priority + preemption: urgent jobs jump the queue."
        ], hook: "Slurm for scientists' batch queues, Kubernetes for container apps, Run:ai to share GPUs fairly." },
        { h: "Virtualizing GPUs", pts: [
          "<b>Passthrough</b>: one whole GPU to one VM, near bare-metal.",
          "<b>vGPU</b>: share GPUs across VMs with NVIDIA vGPU software. Needs a license (NVIDIA AI Enterprise for compute).",
          "<b>MIG</b>: A100/H100-class GPU split into up to <b>7</b> hardware-isolated instances (own compute, memory, cache). Best for guaranteed QoS and multi-tenant isolation.",
          "<b>Time-slicing</b>: processes take turns. No memory or fault isolation. Good for light dev workloads."
        ], hook: "Passthrough = rent the whole house. MIG = apartments with real walls (max 7). Time-slicing = hot-desking, everyone shares one desk." }
      ]
    }
  ],
  traps: [
    "MIG arrived with Ampere (A100), not Hopper. FP8 Transformer Engine arrived with Hopper.",
    "NVLink is inside the node; InfiniBand is between nodes. An answer that uses NVLink to join racks is wrong (except the NVL72 rack-scale domain).",
    "Time-slicing gives no memory isolation. If the question says guaranteed or isolated, pick MIG.",
    "vGPU always means a license. Passthrough gives one VM the whole GPU.",
    "PUE is total ÷ IT, never IT ÷ total. It can never be below 1.0.",
    "RoCE needs PFC and ECN. InfiniBand needs a Subnet Manager.",
    "TensorRT optimizes; Triton serves; NIM packages both behind an API.",
    "OOB management is the network that still works when the server OS is down."
  ],
  questions: [
    // ---------- Domain 1: Essential AI Knowledge (38) ----------
    { d: 1, q: "Which statement best describes the relationship between AI, machine learning (ML), and deep learning (DL)?", o: ["DL is a subset of ML, which is a subset of AI", "ML is a subset of DL, which is a subset of AI", "AI is a subset of ML, which is a subset of DL", "AI, ML and DL are independent fields with no overlap"], a: 0, e: "AI is the broad goal; ML is the subset that learns from data; DL is the subset of ML using multi-layer neural networks. Generative AI sits inside DL." },
    { d: 1, q: "What primarily distinguishes deep learning from classical machine learning?", o: ["Deep learning uses multi-layer neural networks that learn features automatically from raw data", "Deep learning requires no training data", "Deep learning only runs on CPUs", "Deep learning relies on hand-crafted rules written by experts"], a: 0, e: "Classical ML usually depends on engineered features. DL learns a hierarchy of features itself, which is why it needs lots of data and GPU compute." },
    { d: 1, q: "Which combination of factors is most responsible for the rapid adoption of AI in the last decade?", o: ["Large datasets, GPU-accelerated compute, and improved algorithms such as transformers", "Cheaper hard disk drives and faster single-core CPUs alone", "The decline of cloud computing", "Replacement of neural networks by rule-based expert systems"], a: 0, e: "Remember D-C-A: Data, Compute (GPUs), Algorithms (deep nets, transformers), plus mature software frameworks." },
    { d: 1, q: "A workload performs millions of identical, independent math operations on large matrices. Which processor fits best and why?", o: ["GPU, because thousands of cores run the operations in parallel for high throughput", "CPU, because a few powerful cores minimize per-instruction latency", "CPU, because it has larger caches per core", "GPU, because it is optimized for branch-heavy sequential code"], a: 0, e: "GPUs are throughput machines built for parallel math. CPUs are latency machines built for serial, branchy logic." },
    { d: 1, q: "Which workload would benefit LEAST from GPU acceleration?", o: ["A single-threaded, branch-heavy business rules engine", "Training a convolutional neural network", "Video transcoding and rendering", "Large dataframe joins and aggregations with RAPIDS"], a: 0, e: "Accelerated computing helps when work can be parallelized. Serial, decision-heavy code runs best on the CPU." },
    { d: 1, q: "What is the main purpose of Tensor Cores in NVIDIA GPUs?", o: ["Accelerate matrix multiply-accumulate operations used in deep learning, often at mixed precision", "Encrypt data stored in GPU memory", "Route network packets between servers", "Increase the GPU's memory capacity"], a: 0, e: "Tensor Cores (first in Volta) perform fused matrix math at reduced precisions such as FP16, BF16, TF32, FP8 and FP4." },
    { d: 1, q: "Which feature introduced with the Hopper architecture dynamically uses FP8 precision to speed up transformer models?", o: ["Transformer Engine", "Multi-Instance GPU", "NVLink-C2C", "GPUDirect Storage"], a: 0, e: "Hopper's Transformer Engine mixes FP8 and FP16 per layer. Blackwell's second-generation engine adds FP4. MIG came earlier, with Ampere." },
    { d: 1, q: "Which ordering of NVIDIA data center GPU architectures is correct, oldest to newest?", o: ["Volta → Ampere → Hopper → Blackwell", "Ampere → Volta → Blackwell → Hopper", "Hopper → Ampere → Volta → Blackwell", "Volta → Hopper → Ampere → Blackwell"], a: 0, e: "V100 (Volta) → A100 (Ampere) → H100 (Hopper) → B200/GB200 (Blackwell). Hook: Very Awesome Hackers Build." },
    { d: 1, q: "What is CUDA?", o: ["NVIDIA's parallel computing platform and programming model for running general-purpose code on GPUs", "A deep learning framework that competes with PyTorch", "A GPU monitoring daemon", "A high-speed networking protocol"], a: 0, e: "CUDA is the foundation layer. cuDNN, cuBLAS, NCCL and frameworks like PyTorch are built on top of it." },
    { d: 1, q: "Which NVIDIA library provides GPU-accelerated primitives such as convolutions and activation functions to deep learning frameworks?", o: ["cuDNN", "NCCL", "DCGM", "DOCA"], a: 0, e: "cuDNN = deep neural network primitives. NCCL = multi-GPU communication. DCGM = GPU monitoring. DOCA = DPU SDK." },
    { d: 1, q: "During multi-GPU training, gradients must be summed across all GPUs after each step. Which NVIDIA library performs this all-reduce efficiently over NVLink and InfiniBand?", o: ["NCCL", "TensorRT", "cuDF", "Triton Inference Server"], a: 0, e: "NCCL (Collective Communications Library) implements topology-aware all-reduce, broadcast and all-gather." },
    { d: 1, q: "A team wants to cut the latency of a trained model in production using layer fusion, kernel auto-tuning and INT8/FP8 quantization. Which tool should they use?", o: ["TensorRT", "RAPIDS", "NeMo Curator", "Base Command Manager"], a: 0, e: "TensorRT (and TensorRT-LLM for LLMs) compiles a trained model into an optimized inference engine." },
    { d: 1, q: "Which is a key capability of NVIDIA Triton Inference Server?", o: ["Serving models from many frameworks (PyTorch, TensorFlow, ONNX, TensorRT) with dynamic batching and concurrent model execution", "Training models with data parallelism", "Provisioning bare-metal cluster nodes", "Encrypting traffic on the DPU"], a: 0, e: "Triton is open-source serving software with HTTP/gRPC endpoints, dynamic batching, multiple models per GPU and Prometheus metrics." },
    { d: 1, q: "A company wants prebuilt, optimized containers that expose an industry-standard API so developers can deploy an LLM in minutes on any NVIDIA-accelerated infrastructure. What should they use?", o: ["NVIDIA NIM microservices", "NVIDIA DALI", "NVIDIA DCGM", "CUDA Toolkit"], a: 0, e: "NIM packages a model with optimized inference engines into a container with standard (OpenAI-compatible) APIs. It is part of NVIDIA AI Enterprise." },
    { d: 1, q: "Which NVIDIA framework is used to build, customize (for example fine-tune) and deploy large language and generative AI models end to end?", o: ["NeMo", "Merlin", "Metropolis", "Clara"], a: 0, e: "NeMo covers data curation, training, customization, guardrails and evaluation. Merlin = recommenders, Metropolis = vision AI, Clara = healthcare." },
    { d: 1, q: "A data science team's pandas and scikit-learn pipelines are slow on CPUs. Which NVIDIA suite accelerates them with minimal code changes?", o: ["RAPIDS (cuDF, cuML)", "TensorRT", "Riva", "Isaac Sim"], a: 0, e: "RAPIDS provides GPU dataframes (cuDF, pandas-like) and ML algorithms (cuML, scikit-learn-like), and accelerates Apache Spark." },
    { d: 1, q: "What is the NGC catalog?", o: ["A hub of GPU-optimized containers, pretrained models, Helm charts and SDKs", "NVIDIA's hardware warranty portal", "A configuration tool for InfiniBand switches", "A physical rack design guide"], a: 0, e: "NGC hosts tested, performance-tuned containers (PyTorch, Triton, NeMo and more), models and resources." },
    { d: 1, q: "What does NVIDIA AI Enterprise provide?", o: ["A licensed, supported software platform with security updates and certified frameworks such as NIM, NeMo, Triton and RAPIDS", "A free gaming driver package", "A cloud-only GPU rental service", "A liquid cooling specification"], a: 0, e: "NVIDIA AI Enterprise is the production software layer with enterprise support. Its license also covers vGPU for compute workloads." },
    { d: 1, q: "Which statement correctly compares training and inference requirements?", o: ["Training needs maximum compute, memory and fast GPU-to-GPU links; inference prioritizes latency, throughput per watt and cost at scale", "Inference always needs more GPUs than training", "Training is latency-sensitive while inference is not", "Both require identical hardware and software"], a: 0, e: "Training is heavy, long and multi-GPU. Inference serves many requests under latency targets, often quantized and scaled out, even to the edge." },
    { d: 1, q: "Why is a model often quantized from FP16 to INT8 or FP8 before deployment?", o: ["It reduces memory footprint and increases throughput, usually with a small accuracy loss", "It significantly increases model accuracy", "It is required for training to converge", "It removes the need for a GPU"], a: 0, e: "Fewer bits per value means less memory and faster math. Calibrate and validate to keep accuracy loss small." },
    { d: 1, q: "In inference serving, what is the usual effect of increasing the batch size?", o: ["Higher throughput but potentially higher latency per request", "Lower throughput and lower latency", "No effect on throughput or latency", "Lower memory usage"], a: 0, e: "Larger batches keep the GPU busier (throughput up) but requests wait to fill the batch (latency up). Triton's dynamic batching balances the two." },
    { d: 1, q: "A hospital wants GPU-accelerated medical imaging and genomics workflows. Which NVIDIA platform targets this?", o: ["Clara", "Metropolis", "DRIVE", "Merlin"], a: 0, e: "Clara covers healthcare and life sciences: imaging, genomics (Parabricks) and drug discovery (BioNeMo)." },
    { d: 1, q: "A city wants to analyze video from thousands of traffic cameras. Which NVIDIA application framework fits?", o: ["Metropolis (with DeepStream)", "Riva", "Morpheus", "cuOpt"], a: 0, e: "Metropolis is the vision AI / intelligent video analytics platform. DeepStream builds streaming video pipelines." },
    { d: 1, q: "Which NVIDIA SDK provides GPU-accelerated speech recognition and text-to-speech for conversational AI?", o: ["Riva", "Merlin", "Isaac", "Omniverse"], a: 0, e: "Riva = speech AI: automatic speech recognition, text-to-speech and translation." },
    { d: 1, q: "A security team wants to inspect network traffic in real time with AI to detect threats and data leaks. Which NVIDIA framework is designed for this?", o: ["Morpheus", "Clara", "Merlin", "Riva"], a: 0, e: "Morpheus is NVIDIA's AI cybersecurity framework, often fed by telemetry from BlueField DPUs." },
    { d: 1, q: "An e-commerce company needs to train and serve large-scale recommender systems. Which NVIDIA framework is purpose-built for this?", o: ["Merlin", "Metropolis", "Riva", "DRIVE"], a: 0, e: "Merlin accelerates the full recommender pipeline: data prep, training and inference." },
    { d: 1, q: "Which NVIDIA platform is used to build physically accurate digital twins of factories based on OpenUSD?", o: ["Omniverse", "RAPIDS", "Triton", "NCCL"], a: 0, e: "Omniverse is the OpenUSD platform for 3D simulation and digital twins; Isaac Sim, built on it, simulates robots." },
    { d: 1, q: "Which NVIDIA platform is designed for AI inference in robots, drones and embedded devices at the edge?", o: ["Jetson", "DGX SuperPOD", "HGX", "Quantum InfiniBand"], a: 0, e: "Jetson modules (for example Orin) are compact, low-power edge AI computers. IGX targets industrial and medical edge with functional safety." },
    { d: 1, q: "GPU utilization during training stays low because the CPU cannot decode and augment images fast enough. Which NVIDIA library moves this work to the GPU?", o: ["DALI", "NCCL", "cuBLAS", "DOCA"], a: 0, e: "DALI (Data Loading Library) accelerates decoding and augmentation so the GPUs stay fed." },
    { d: 1, q: "What is the main benefit of mixed-precision training?", o: ["Faster training and lower memory use by computing in FP16/BF16 while keeping critical values in FP32", "It guarantees higher final accuracy than FP32", "It removes the need for Tensor Cores", "It allows training without labeled data"], a: 0, e: "Mixed precision uses Tensor Cores at lower precision for speed, while FP32 master weights preserve accuracy." },
    { d: 1, q: "A retailer groups customers into segments based on purchase behavior, with no predefined labels. What type of learning is this?", o: ["Unsupervised learning", "Supervised learning", "Reinforcement learning", "Transfer learning"], a: 0, e: "No labels and the goal is to find structure (clusters) = unsupervised learning." },
    { d: 1, q: "Which architecture underpins most modern large language models, using self-attention to process tokens in parallel?", o: ["Transformer", "Recurrent neural network (RNN)", "Decision tree", "Support vector machine"], a: 0, e: "Transformers replaced sequential RNNs. Self-attention parallelizes well on GPUs, which allowed LLMs to scale." },
    { d: 1, q: "In data-parallel training, what is replicated and what is split?", o: ["The full model is replicated on every GPU; each training batch is split across GPUs", "The model is split across GPUs; the data is replicated", "Both model and data are replicated with no communication", "Only the optimizer is split; the model is not used"], a: 0, e: "Each GPU processes its slice of the batch, then gradients are synchronized with all-reduce (NCCL)." },
    { d: 1, q: "A 400-billion-parameter model does not fit in a single GPU's memory. Which approach addresses this?", o: ["Model parallelism (tensor and/or pipeline parallelism) across multiple GPUs", "Increasing the batch size", "Moving to a CPU-only cluster", "Using data parallelism alone"], a: 0, e: "Model parallelism splits the model's layers or tensors across GPUs. Data parallelism alone still needs the whole model on each GPU." },
    { d: 1, t: "multi", q: "Which TWO are characteristics of GPU architecture compared with CPU architecture? (Select TWO.)", o: ["Thousands of smaller cores optimized for parallel throughput", "High-bandwidth memory (HBM) to feed many cores", "Few cores optimized for low-latency serial execution", "Large branch predictors as the main design focus", "Designed to run the operating system kernel"], a: [0, 1], e: "GPUs = many cores + HBM bandwidth for throughput. Few powerful cores, branch prediction and running the OS describe CPUs." },
    { d: 1, q: "What is NVIDIA Grace?", o: ["An Arm-based data center CPU, paired with GPUs via NVLink-C2C in Grace Hopper and Grace Blackwell superchips", "A GPU for gaming laptops", "An InfiniBand switch", "A Kubernetes scheduler"], a: 0, e: "NVLink-C2C links the Grace CPU and GPU coherently at 900 GB/s, far faster than PCIe." },
    { d: 1, q: "A company with limited compute wants a custom image classifier. Which approach is most efficient?", o: ["Fine-tune a pretrained model (for example from NGC) on its own labeled images", "Train a large model from scratch", "Write rule-based image filters", "Use reinforcement learning with no labels"], a: 0, e: "Transfer learning reuses what a pretrained model already knows, so far less data and compute are needed." },
    { d: 1, q: "Which sequence describes a typical AI lifecycle using NVIDIA software?", o: ["Data preparation (RAPIDS/DALI) → training (PyTorch, NeMo, NCCL) → optimization (TensorRT) → deployment (Triton/NIM) → monitoring", "Deployment (Triton) → training (NeMo) → data preparation (RAPIDS) → optimization (TensorRT)", "Optimization (TensorRT) → data preparation → deployment → training", "Monitoring → deployment → training → data preparation"], a: 0, e: "Prepare → Train → Optimize → Serve → Monitor." },

    // ---------- Domain 2: AI Infrastructure (40) ----------
    { d: 2, q: "What is the primary purpose of NVLink?", o: ["High-bandwidth, low-latency direct GPU-to-GPU communication, far exceeding PCIe", "Connecting servers across distant racks", "Connecting storage arrays to the management network", "Providing out-of-band BMC access"], a: 0, e: "NVLink connects GPUs inside a node (and across an NVL72 rack). H100 NVLink 4 = 900 GB/s per GPU; Blackwell NVLink 5 = 1.8 TB/s." },
    { d: 2, q: "What role does NVSwitch play in a DGX/HGX system?", o: ["It connects all GPUs so every GPU can talk to every other GPU at full NVLink bandwidth", "It connects the server to the InfiniBand fabric", "It replaces the CPU for job scheduling", "It manages power distribution"], a: 0, e: "NVSwitch builds an all-to-all NVLink fabric among the GPUs. Inter-node traffic goes over ConnectX NICs." },
    { d: 2, q: "GB200 NVL72 is best described as:", o: ["A liquid-cooled rack-scale system with 72 Blackwell GPUs and 36 Grace CPUs acting as one NVLink domain", "An air-cooled workstation with 2 GPUs", "A 72-port InfiniBand switch", "A software license tier"], a: 0, e: "NVL72 extends NVLink/NVSwitch across a whole rack. Rack power is roughly 120 kW or more, so liquid cooling is required." },
    { d: 2, q: "Which are key characteristics of InfiniBand for AI clusters?", o: ["Lossless credit-based flow control, native RDMA and very low latency", "Best-effort delivery with drops handled by TCP", "Designed only for storage, not compute", "Requires no fabric management"], a: 0, e: "InfiniBand is natively lossless with RDMA. Quantum-2 NDR runs 400 Gb/s per port; Quantum-X800 XDR runs 800 Gb/s." },
    { d: 2, q: "In an InfiniBand fabric, which component discovers the topology, assigns addresses (LIDs) and computes routing tables?", o: ["Subnet Manager (for example in UFM or on a managed switch)", "Spanning Tree Protocol", "A DHCP server", "A BGP route reflector"], a: 0, e: "Every InfiniBand fabric needs an active Subnet Manager. Without it, ports never become active." },
    { d: 2, q: "A company wants RDMA performance on its existing Ethernet switches. What must be configured for RoCE v2 to perform well?", o: ["Lossless Ethernet using Priority Flow Control (PFC) and Explicit Congestion Notification (ECN)", "Jumbo frames only", "Spanning Tree Protocol on all ports", "Disabling QoS entirely"], a: 0, e: "Ethernet is lossy by default. PFC and ECN make it behave near-lossless for RDMA. NVIDIA Spectrum-X is tuned for this." },
    { d: 2, q: "What does GPUDirect RDMA enable?", o: ["The network adapter reads and writes GPU memory directly, bypassing the CPU and system memory", "GPUs share memory with the CPU over NVLink-C2C", "Storage is mounted directly as GPU memory without a network", "Two VMs share one GPU"], a: 0, e: "Removing the copy through host memory lowers latency and CPU overhead for multi-node training." },
    { d: 2, q: "Training jobs spend a lot of time loading data from NVMe through CPU bounce buffers. Which technology creates a direct path from storage to GPU memory?", o: ["GPUDirect Storage", "GPUDirect P2P", "Multi-Instance GPU", "NVLink-C2C"], a: 0, e: "GPUDirect Storage lets DMA engines move data straight between storage and GPU memory." },
    { d: 2, q: "What is the main purpose of a DPU such as NVIDIA BlueField?", o: ["Offload, accelerate and isolate infrastructure tasks (networking, storage, security) from the host CPU", "Replace the GPU for model training", "Act as the server's main application CPU", "Store model checkpoints"], a: 0, e: "CPU runs apps, GPU runs AI math, DPU runs the infrastructure plumbing. BlueField is programmed with DOCA." },
    { d: 2, q: "Which is a security benefit of running infrastructure services on a DPU?", o: ["Security functions run in a domain isolated from the host, so a compromised host cannot easily disable them", "It removes the need for any firewall", "It encrypts GPU memory during training", "It eliminates the need for patching"], a: 0, e: "This supports zero-trust: firewalling, micro-segmentation and telemetry are enforced on the DPU, not on the tenant-controlled host." },
    { d: 2, q: "How many GPUs are in a single NVIDIA DGX H100 system?", o: ["8", "4", "16", "72"], a: 0, e: "DGX H100, H200 and B200 each have 8 GPUs connected by NVSwitch. 72 is the GB200 NVL72 rack." },
    { d: 2, q: "Approximately what maximum power draw should be planned for one DGX H100 system?", o: ["About 10.2 kW", "About 1.5 kW", "About 3 kW", "About 50 kW"], a: 0, e: "DGX H100 is about 10.2 kW max (DGX A100 about 6.5 kW). Four DGX H100s exceed 40 kW in one rack." },
    { d: 2, q: "What is NVIDIA DGX SuperPOD?", o: ["A turnkey, validated AI data center architecture of many DGX systems built from scalable units with InfiniBand, storage and management software", "A single desktop AI workstation", "A cloud billing plan", "A GPU monitoring dashboard"], a: 0, e: "BasePOD is the reference architecture for smaller deployments; SuperPOD is the full-scale, turnkey AI factory." },
    { d: 2, q: "In AI data center networking, east-west traffic refers to:", o: ["Traffic between servers inside the cluster, such as GPU-to-GPU gradient exchange", "Traffic between internet users and the data center", "Traffic on the out-of-band network only", "Power distribution across rows"], a: 0, e: "North-south is traffic in and out of the data center. Distributed training is dominated by east-west traffic." },
    { d: 2, q: "A DGX SuperPOD typically separates which networks?", o: ["Compute fabric, storage fabric, in-band management and out-of-band management", "A single flat Ethernet network", "Wi-Fi and Bluetooth", "Only compute and internet"], a: 0, e: "Separation keeps storage and management traffic away from latency-sensitive GPU communication and improves security." },
    { d: 2, q: "What is the purpose of the out-of-band (OOB) management network?", o: ["Access to BMCs for power control, console and hardware health even when the OS is down", "Carrying GPU-to-GPU training traffic", "Serving inference requests to customers", "Replicating storage data"], a: 0, e: "BMC interfaces (IPMI/Redfish) allow remote power cycling, firmware updates and console access independent of the OS." },
    { d: 2, q: "What is a rail-optimized network topology?", o: ["GPU n's NIC in every server connects to the same leaf switch (rail), minimizing hops for collective operations", "All servers connect to a single core switch with no leaves", "Servers are daisy-chained in a ring", "Storage is placed on the same rail as power"], a: 0, e: "Rails keep matching GPUs one switch hop apart, which suits NCCL collectives." },
    { d: 2, q: "Why are AI compute fabrics usually designed as non-blocking fat-tree topologies?", o: ["To provide full bisection bandwidth so any node can talk to any other at full speed", "To minimize cables at the cost of bandwidth", "To force all traffic through one core switch", "To allow lossy delivery"], a: 0, e: "Non-blocking = no oversubscription. Collective operations need every link at full speed." },
    { d: 2, q: "A facility consumes 1.5 MW in total, of which IT equipment consumes 1.0 MW. What is its PUE?", o: ["1.5", "0.67", "2.5", "1.0"], a: 0, e: "PUE = total facility power ÷ IT equipment power = 1.5 ÷ 1.0 = 1.5. Ideal is 1.0; lower is better." },
    { d: 2, q: "Rack densities for new GPU systems exceed what air cooling can remove. Which cooling approach is most appropriate?", o: ["Direct-to-chip liquid cooling", "Adding more ceiling fans", "Lowering room humidity", "Spreading GPUs across office space"], a: 0, e: "Air cooling tops out around 30–40 kW per rack. Direct-to-chip liquid cooling handles 100 kW+ racks such as NVL72." },
    { d: 2, q: "What does hot aisle / cold aisle containment achieve?", o: ["Prevents hot exhaust air from mixing with cold intake air, improving cooling efficiency", "Separates network cables from power cables", "Keeps technicians out of the server room", "Reduces the GPUs' electrical load"], a: 0, e: "Containment keeps intake air cold and returns hot air directly to the cooling units, improving PUE." },
    { d: 2, q: "Why are redundant power supplies (N+1 or N+N) and dual power feeds recommended for DGX systems?", o: ["So a single PSU or feed failure does not take down long-running training jobs", "They double GPU compute performance", "They are required for NVLink to work", "They reduce cooling requirements"], a: 0, e: "Training runs last days or weeks. Redundancy keeps them alive through component or feed failures." },
    { d: 2, q: "Which is a key advantage of on-premises AI infrastructure over public cloud?", o: ["Data sovereignty and control, and lower total cost when GPUs are highly utilized for years", "Instant elastic scaling with no capacity planning", "No upfront capital expenditure", "No need for power or cooling planning"], a: 0, e: "On-prem wins on control and steady high utilization. Cloud wins on elasticity, speed to start and OPEX." },
    { d: 2, q: "A startup needs GPUs for a three-month experiment with unpredictable demand. Which deployment model fits best?", o: ["Public cloud GPU instances", "Building a new on-prem data center", "Buying a DGX SuperPOD", "Deploying Jetson devices"], a: 0, e: "Short, spiky, uncertain demand = rent elastic capacity (OPEX), no lead time." },
    { d: 2, q: "An enterprise runs steady training on-prem but needs extra capacity before a product launch. What approach is this?", o: ["Hybrid cloud bursting", "Edge computing", "Air-gapped deployment", "Vertical scaling"], a: 0, e: "Hybrid: baseline on-prem, burst peaks to the cloud." },
    { d: 2, q: "Which storage is typically recommended for large-scale, multi-node training datasets?", o: ["High-performance parallel file systems (for example Lustre, IBM Storage Scale, WEKA)", "A single NAS on 1 GbE", "Tape libraries", "Local USB drives"], a: 0, e: "Many GPUs reading at once need high aggregate throughput, which parallel file systems provide." },
    { d: 2, q: "Long training runs periodically save model checkpoints. What storage requirement does this create?", o: ["High write bandwidth to absorb large checkpoint bursts without stalling GPUs", "Very low capacity", "Read-optimized storage only", "None; checkpoints stay in GPU memory"], a: 0, e: "Checkpoints are large and written all at once. Slow writes leave expensive GPUs idle." },
    { d: 2, q: "An organization wants to pre-train an LLM with hundreds of billions of parameters. Which infrastructure is most appropriate?", o: ["Multi-node 8-GPU HGX/DGX systems (H100/B200 class) with NVLink inside nodes and InfiniBand between nodes", "A single workstation with one RTX GPU", "Jetson devices networked over Wi-Fi", "CPU-only virtual machines"], a: 0, e: "Large-model training needs scale-up (NVLink) and scale-out (InfiniBand) together." },
    { d: 2, q: "Which GPU is typically most cost- and power-efficient for high-volume video and lightweight AI inference in standard servers?", o: ["A low-profile, low-power inference GPU such as NVIDIA L4", "A full GB200 NVL72 rack", "A GPU optimized only for FP64 HPC", "No GPU; CPUs are always more efficient"], a: 0, e: "L4 (about 72 W) targets efficient inference and video. L40S targets mixed graphics and AI. H100/B200 target heavy training and large-model inference." },
    { d: 2, q: "What is the difference between scaling up and scaling out GPU infrastructure?", o: ["Scale up adds more or bigger GPUs within a node (NVLink); scale out adds more nodes over the network (InfiniBand/Ethernet)", "Scale up adds nodes; scale out adds GPU memory", "They mean the same thing", "Scale out only applies to storage"], a: 0, e: "Up = inside the box. Out = more boxes." },
    { d: 2, q: "What per-port speed does NDR InfiniBand (Quantum-2, ConnectX-7) provide?", o: ["400 Gb/s", "10 Gb/s", "100 Mb/s", "4 Tb/s"], a: 0, e: "HDR = 200 Gb/s, NDR = 400 Gb/s, XDR = 800 Gb/s." },
    { d: 2, q: "What is NVIDIA Spectrum-X?", o: ["An Ethernet networking platform (Spectrum switches + SuperNICs) optimized for AI with RoCE, adaptive routing and congestion control", "An InfiniBand subnet manager", "A GPU cooling system", "A vGPU license tier"], a: 0, e: "Spectrum-X brings InfiniBand-like AI performance to Ethernet." },
    { d: 2, q: "When planning a facility for AI racks, which requirements must be verified besides electrical power?", o: ["Cooling capacity, floor weight loading, space and cabling", "Only internet bandwidth", "Only the number of desks", "Only the server brand"], a: 0, e: "Dense GPU racks are heavy, hot and power-hungry. Check power density, cooling, floor load, cabling and redundancy." },
    { d: 2, t: "multi", q: "Which TWO are benefits of InfiniBand for distributed training? (Select TWO.)", o: ["Native RDMA with very low latency", "Lossless transport with credit-based flow control", "Relies on TCP retransmissions for reliability", "Optimized for wireless clients", "Works without any switches"], a: [0, 1], e: "InfiniBand is RDMA-native and lossless by design. TCP retransmission is the opposite of what collectives need." },
    { d: 2, q: "Why is the storage network often physically separated from the GPU compute fabric?", o: ["So storage traffic does not interfere with latency-sensitive collective communication between GPUs", "Because storage cannot use Ethernet", "Because GPUs cannot read from storage", "To reduce the number of servers"], a: 0, e: "Mixing bulk storage I/O with all-reduce traffic causes congestion and jitter." },
    { d: 2, q: "Scaling a training job from 8 to 64 GPUs gives only a 3x speedup. Profiling shows GPUs waiting during all-reduce. What is the most likely fix?", o: ["Improve the inter-node fabric: more or faster InfiniBand NICs and a non-blocking, rail-optimized topology", "Add more CPU RAM", "Use a larger monitor", "Remove NVLink bridges"], a: 0, e: "Waiting on all-reduce means communication is the bottleneck. Improve network bandwidth and topology." },
    { d: 2, q: "Which interconnect connects the CPU to GPUs in a typical x86 server and is much slower than NVLink?", o: ["PCIe", "NVSwitch", "InfiniBand", "NVLink-C2C"], a: 0, e: "PCIe Gen5 x16 is roughly 128 GB/s bidirectional versus 900 GB/s for H100 NVLink." },
    { d: 2, q: "What is DOCA?", o: ["The software framework and SDK for programming NVIDIA BlueField DPUs", "A GPU monitoring dashboard", "A deep learning framework", "A data center cooling standard"], a: 0, e: "DOCA is to the DPU what CUDA is to the GPU." },
    { d: 2, q: "A team wants a managed, multi-node NVIDIA AI training platform in the cloud with NVIDIA software included. Which offering fits?", o: ["NVIDIA DGX Cloud", "Jetson Orin", "NVIDIA Riva", "An RTX workstation"], a: 0, e: "DGX Cloud is NVIDIA's AI platform hosted with cloud partners, including NVIDIA AI Enterprise software." },
    { d: 2, q: "What is the main difference between HGX and DGX?", o: ["HGX is the GPU baseboard platform that OEMs build servers on; DGX is NVIDIA's complete integrated system with software and support", "HGX is for gaming; DGX is for laptops", "HGX is an InfiniBand switch; DGX is a DPU", "They are identical names for the same product"], a: 0, e: "OEMs such as Dell, HPE and Supermicro build HGX-based servers. DGX is NVIDIA's own turnkey system." },

    // ---------- Domain 3: AI Operations (22) ----------
    { d: 3, q: "What is NVIDIA DCGM primarily used for?", o: ["Managing and monitoring GPUs at data center scale: health checks, diagnostics, telemetry and policies", "Training models", "Compiling CUDA kernels", "Configuring InfiniBand routing"], a: 0, e: "DCGM = Data Center GPU Manager. Its exporter feeds Prometheus and Grafana." },
    { d: 3, q: "An administrator needs a quick view of GPU utilization, memory use, temperature and running processes on one server. Which tool?", o: ["nvidia-smi", "NCCL", "TensorRT", "DOCA"], a: 0, e: "nvidia-smi is the per-node CLI. Use DCGM for fleet-wide monitoring." },
    { d: 3, q: "How are GPU metrics typically collected cluster-wide in Kubernetes for dashboards and alerts?", o: ["DCGM Exporter exposes metrics to Prometheus, visualized in Grafana", "nvidia-smi output is emailed hourly", "TensorRT logs are posted to chat", "BMC SNMP traps only"], a: 0, e: "The GPU Operator deploys DCGM Exporter; Prometheus scrapes it; Grafana dashboards and alerts sit on top." },
    { d: 3, q: "What do XID errors in the system log indicate?", o: ["GPU driver-reported error events (for example memory faults or a GPU falling off the bus) used for troubleshooting", "Normal GPU clock changes", "Successful job completions", "Network link speeds"], a: 0, e: "XID codes map to specific failures, for example XID 79 = GPU fell off the bus and XID 48 = double-bit ECC error." },
    { d: 3, q: "DCGM reports increasing uncorrectable (double-bit) ECC errors on one GPU. What is the best action?", o: ["Drain the node from the scheduler, run diagnostics and plan GPU replacement", "Ignore it because ECC fixes all errors", "Increase the GPU clock", "Disable ECC to stop the alerts"], a: 0, e: "Single-bit errors are corrected. Uncorrectable errors risk corrupted results and crashes." },
    { d: 3, q: "Training throughput drops every afternoon, and nvidia-smi shows reduced clocks with a thermal slowdown reason. What is the cause?", o: ["Thermal throttling due to insufficient cooling", "An expired software license", "A smaller dataset", "An NCCL version mismatch"], a: 0, e: "GPUs lower clocks to protect themselves when too hot. Fix airflow or cooling capacity." },
    { d: 3, q: "GPU utilization averages 30% while CPU cores are at 100% loading data. What is the most likely bottleneck?", o: ["The data pipeline (CPU preprocessing or storage I/O) is starving the GPUs", "The GPUs are too fast and should be replaced", "An NVLink bridge is missing", "ECC is enabled"], a: 0, e: "Fix with DALI, more data loader workers, caching, faster storage or GPUDirect Storage." },
    { d: 3, q: "Which workload manager is widely used on HPC and DGX SuperPOD clusters for batch jobs, with commands like sbatch and srun?", o: ["Slurm", "Docker Compose", "Ansible", "Grafana"], a: 0, e: "Slurm allocates nodes and GPUs (GRES) to batch jobs. Pyxis/Enroot add container support." },
    { d: 3, q: "How does Kubernetes make GPUs schedulable to pods?", o: ["Through the NVIDIA device plugin, which advertises the resource nvidia.com/gpu", "Natively, with no extra components", "Through the BMC", "By mounting /dev/gpu as a ConfigMap"], a: 0, e: "Pods request nvidia.com/gpu in their resource limits. The GPU Operator deploys the device plugin." },
    { d: 3, q: "What does the NVIDIA GPU Operator automate on Kubernetes?", o: ["Deployment of GPU drivers, container toolkit, device plugin, DCGM exporter and MIG manager", "Hyperparameter tuning", "InfiniBand cable installation", "Application code review"], a: 0, e: "It turns every GPU node into a ready-to-use node without manual driver installs. The Network Operator does the same for networking." },
    { d: 3, q: "An organization wants fair-share GPU quotas across teams, fractional GPUs and dynamic pooling on Kubernetes. Which NVIDIA product fits?", o: ["NVIDIA Run:ai", "NVIDIA Riva", "NVIDIA Clara", "CUDA Toolkit"], a: 0, e: "Run:ai adds an AI-aware scheduler: quotas, fair share, fractional GPUs and gang scheduling." },
    { d: 3, q: "Which NVIDIA software provisions OS images, manages and monitors nodes, and sets up Slurm or Kubernetes on AI clusters?", o: ["NVIDIA Base Command Manager", "NVIDIA Omniverse", "NVIDIA Merlin", "TensorRT"], a: 0, e: "Base Command Manager is the cluster management layer for DGX and other GPU clusters." },
    { d: 3, q: "What is Multi-Instance GPU (MIG)?", o: ["Partitioning one A100/H100-class GPU into up to 7 hardware-isolated instances with dedicated compute and memory", "Combining multiple GPUs into one large GPU", "Time-sharing a GPU between processes with no isolation", "Running GPUs inside a DPU"], a: 0, e: "Each MIG instance has its own SMs, memory and cache, giving predictable performance and fault isolation." },
    { d: 3, q: "What is the main limitation of GPU time-slicing compared with MIG?", o: ["No memory or fault isolation; workloads share GPU memory and take turns", "It only works on CPUs", "It requires InfiniBand", "It allows only one container per GPU"], a: 0, e: "Time-slicing is fine for light development work but not for guaranteed QoS or multi-tenant isolation." },
    { d: 3, q: "Several VMs on a hypervisor must share physical GPUs with NVIDIA-supported drivers. What is required?", o: ["NVIDIA vGPU software with the appropriate license (for example NVIDIA AI Enterprise for compute)", "Nothing; hypervisors share GPUs natively", "A DPU inside each VM", "Slurm"], a: 0, e: "vGPU needs a host driver, guest drivers and a license server. vGPU can be time-sliced or MIG-backed." },
    { d: 3, q: "A single VM needs exclusive, near bare-metal access to an entire GPU. Which approach?", o: ["PCIe passthrough (direct device assignment)", "Time-slicing", "MIG with 7 instances", "CPU emulation"], a: 0, e: "Passthrough gives one VM the whole GPU with minimal overhead, at the cost of sharing." },
    { d: 3, q: "A provider hosts inference for several customers on one H100 and must guarantee each gets predictable performance and isolated memory. Which option is best?", o: ["MIG", "Time-slicing", "Running all customers in one process", "Disabling ECC"], a: 0, e: "Guaranteed QoS + isolation = MIG." },
    { d: 3, q: "An admin wants to validate a new node's GPUs, PCIe, NVLink and memory before production. What should they run?", o: ["DCGM diagnostics (dcgmi diag) at an appropriate run level", "nvidia-smi once", "A web browser benchmark", "Only the TensorRT trtexec tool"], a: 0, e: "dcgmi diag has quick, medium and long run levels covering software, PCIe, memory, NVLink and stress tests." },
    { d: 3, q: "Which component lets container runtimes such as Docker and containerd use NVIDIA GPUs?", o: ["NVIDIA Container Toolkit", "NVIDIA DOCA", "NVIDIA Omniverse", "NVIDIA cuOpt"], a: 0, e: "The Container Toolkit configures the runtime to expose GPUs and driver libraries inside containers." },
    { d: 3, t: "multi", q: "Which TWO indicators point to a hardware problem on a GPU? (Select TWO.)", o: ["Rising ECC error counts", "XID errors in the system log", "A large batch size", "A low learning rate", "A high number of epochs"], a: [0, 1], e: "ECC and XID errors are hardware and driver health signals. Batch size, learning rate and epochs are training settings." },
    { d: 3, q: "In Kubernetes, a high-priority inference workload must start immediately even when the cluster is full of training jobs. Which feature supports this?", o: ["Priority classes with preemption", "Disabling the scheduler", "Increasing log verbosity", "Using a larger container image"], a: 0, e: "Higher-priority pods can preempt lower-priority ones to free GPUs." },
    { d: 3, q: "A multi-node training job needs all of its workers to start at the same time; partial starts waste GPUs. Which scheduling concept addresses this?", o: ["Gang scheduling", "Round-robin DNS", "Log rotation", "Horizontal pod autoscaling"], a: 0, e: "Slurm allocates all nodes of a job together. On Kubernetes, AI schedulers such as Run:ai provide gang scheduling." }
  ]
};

// NCA-AIIO scenario set: 100 original exam-style questions. l = difficulty (e easy, m medium, h hard).
window.BANKS.nvidia.questions = window.BANKS.nvidia.questions.concat([
  // ===== Domain 1: Essential AI Knowledge (38) =====
  { d: 1, l: "e", q: "A radiology team trains a convolutional neural network on thousands of labeled CT scans to flag possible tumors. A manager says the project is 'machine learning, not deep learning.' Which description is most accurate?", o: ["It is deep learning, which is also a form of machine learning and AI", "It is classical machine learning because the data is labeled", "It is rule-based AI because doctors define the labels", "It is reinforcement learning because the model receives feedback"], a: 0, e: "A CNN is a multi-layer neural network, so it is deep learning. Deep learning sits inside ML, which sits inside AI. Labeled data makes it supervised, not 'non-deep'." },
  { d: 1, l: "e", q: "A marketing startup builds an application that writes new product descriptions and social posts from a few keywords. Which category of AI is this?", o: ["Generative AI", "Predictive analytics with regression", "Unsupervised clustering", "Rule-based expert system"], a: 0, e: "Creating new content (text, images, code) is generative AI, typically powered by transformer-based LLMs." },
  { d: 1, l: "e", q: "A CIO asks which hardware development most directly made it practical to train today's very large neural networks in weeks instead of years. What is the best answer?", o: ["GPU-accelerated computing with massive parallelism and high-bandwidth memory", "Faster hard disk drives", "Higher single-core CPU clock speeds", "Larger monitors for data scientists"], a: 0, e: "Neural network training is dominated by parallel matrix math. GPUs (and Tensor Cores) made that math fast enough, alongside large datasets and better algorithms." },
  { d: 1, l: "e", q: "A courier company must re-plan routes for 5,000 delivery vehicles every morning, and the CPU-based solver is too slow. Which NVIDIA software is designed for this?", o: ["cuOpt", "Riva", "Clara", "DeepStream"], a: 0, e: "cuOpt is NVIDIA's GPU-accelerated decision optimization engine for routing and logistics problems." },
  { d: 1, l: "e", q: "A bank's Apache Spark ETL jobs run for hours on a CPU cluster. The data team wants GPU acceleration without rewriting its Spark code. What should it use?", o: ["RAPIDS Accelerator for Apache Spark", "TensorRT", "NeMo Guardrails", "Triton Inference Server"], a: 0, e: "The RAPIDS Accelerator is a Spark plugin that runs supported SQL and DataFrame operations on GPUs with little or no code change." },
  { d: 1, l: "e", q: "A team keeps hitting CUDA and library version conflicts when building its own PyTorch training images. What is the fastest way to get a tested, GPU-optimized environment?", o: ["Pull the PyTorch container from the NGC catalog", "Compile PyTorch from source on every node", "Use a CPU-only Python virtual environment", "Download drivers from a third-party mirror"], a: 0, e: "NGC containers bundle CUDA, cuDNN, NCCL and the framework in versions NVIDIA has tested together, and they are updated monthly." },
  { d: 1, l: "e", q: "A contact center must transcribe customer calls in real time, on-premises, for privacy reasons. Which NVIDIA SDK fits?", o: ["Riva", "Merlin", "cuOpt", "Omniverse"], a: 0, e: "Riva provides GPU-accelerated speech recognition (ASR), text-to-speech and translation that can run on-premises." },
  { d: 1, l: "e", q: "A retailer wants to test a shelf-scanning robot in a physically accurate virtual warehouse before deploying it. Which NVIDIA technology fits?", o: ["Isaac Sim, built on Omniverse", "RAPIDS cuDF", "NCCL", "DCGM"], a: 0, e: "Isaac Sim simulates robots in realistic environments built on Omniverse and OpenUSD, so behavior can be validated before deployment." },
  { d: 1, l: "e", q: "A data scientist installs PyTorch on a GPU server, but training runs only on the CPU. What is most likely missing?", o: ["The NVIDIA GPU driver and a CUDA-enabled framework build", "A larger hard disk", "An InfiniBand switch", "A Slurm license"], a: 0, e: "Frameworks reach the GPU through the NVIDIA driver and CUDA libraries. A CPU-only build or a missing driver forces CPU execution. NGC containers avoid this." },
  { d: 1, l: "e", q: "A developer with little ML experience must put a popular open LLM behind an OpenAI-compatible API on the company's GPU servers this week, with enterprise support. What is the best choice?", o: ["Deploy the model as an NVIDIA NIM microservice", "Write custom CUDA kernels for the model", "Train a new LLM from scratch with NeMo", "Serve the model from a CPU-only web server"], a: 0, e: "NIM packages an optimized model and inference engine in a container with standard APIs, supported under NVIDIA AI Enterprise." },

  { d: 1, l: "m", q: "A company runs two AI workloads: nightly retraining of a recommendation model on 2 TB of data, and serving recommendations to 10 million users with under 50 ms latency. Which statement about infrastructure is most accurate?", o: ["Training favors multi-GPU nodes with fast interconnects for throughput; serving favors low latency, scale-out replicas and cost per inference, and may use different GPUs", "Both workloads need identical hardware, so one cluster design fits both", "Serving needs more GPU memory and faster interconnects than training", "Training is latency-sensitive while serving is throughput-only"], a: 0, e: "Training and inference have different priorities. Many organizations train on HGX/DGX systems and serve on inference-optimized GPUs such as L4 or L40S, or on MIG slices." },
  { d: 1, l: "m", q: "A team trains a transformer model on H100 GPUs entirely in FP32. Which change uses Hopper's Transformer Engine to speed up training with minimal accuracy impact?", o: ["Enable FP8 mixed-precision training through Transformer Engine", "Switch all math to FP64", "Disable Tensor Cores", "Reduce the number of GPUs to one"], a: 0, e: "Transformer Engine dynamically chooses FP8 or 16-bit precision per layer with scaling to preserve accuracy. FP64 would be slower." },
  { d: 1, l: "m", q: "After converting a model to a TensorRT engine with INT8, throughput tripled but accuracy dropped beyond the acceptable limit. What is the best next step?", o: ["Calibrate INT8 with representative data, or keep sensitive layers in FP16/FP8, then re-validate accuracy", "Abandon GPU inference and move to CPUs", "Increase the batch size until accuracy recovers", "Remove the validation step"], a: 0, e: "Quantization needs good calibration data. Mixed precision (keeping sensitive layers at higher precision) recovers accuracy while keeping most of the speedup." },
  { d: 1, l: "m", q: "A company serves 12 small models, each on its own dedicated GPU. Each model gets little traffic and every GPU runs at about 5% utilization. What is the most efficient fix?", o: ["Consolidate the models onto fewer GPUs with Triton Inference Server's concurrent model execution, or partition GPUs with MIG", "Buy 12 more GPUs for redundancy", "Rewrite all models in C++", "Increase each model's batch size to 1,024"], a: 0, e: "Triton can host many models on one GPU and run them concurrently. MIG can also split a large GPU into isolated slices, raising utilization." },
  { d: 1, l: "m", q: "An inference service receives many single-image requests. GPU utilization is low, average latency is 10 ms and the SLA allows 100 ms. Which Triton feature raises throughput while staying within the SLA?", o: ["Dynamic batching with a configured maximum queue delay", "Disabling batching entirely", "Running the model in FP64", "Moving preprocessing to a single CPU thread"], a: 0, e: "Dynamic batching groups individual requests on the server. The queue delay setting caps how long a request waits, keeping latency within budget." },
  { d: 1, l: "m", q: "A company's LLM assistant must refuse off-topic requests, never discuss competitors and follow a defined dialog flow. Which NVIDIA tool adds these programmable rules?", o: ["NeMo Guardrails", "NCCL", "DALI", "cuOpt"], a: 0, e: "NeMo Guardrails adds programmable input, output and dialog rails around LLM applications." },
  { d: 1, l: "m", q: "A research group is preparing trillions of tokens of web text for LLM pre-training and needs GPU-accelerated deduplication, quality filtering and PII removal at scale. Which tool fits?", o: ["NeMo Curator", "Triton Inference Server", "DeepStream", "Base Command Manager"], a: 0, e: "NeMo Curator is the data curation component of NeMo for building high-quality training datasets." },
  { d: 1, l: "m", q: "An enterprise wants an LLM to answer questions from internal policy documents that change daily. It does not want to retrain the model each day. Which approach fits best?", o: ["Retrieval-augmented generation (RAG) with an embedding model and a vector database, for example with NeMo Retriever", "Pre-train a new LLM every night", "Raise the sampling temperature", "Fine-tune the model once and never update it"], a: 0, e: "RAG retrieves current documents at query time and passes them to the LLM, so answers stay current without retraining." },
  { d: 1, l: "m", q: "A legal-tech startup has 4 GPUs and wants to adapt a 13-billion-parameter LLM to legal writing style at low cost. Which approach is most practical?", o: ["Parameter-efficient fine-tuning such as LoRA, for example with NeMo", "Full pre-training from random weights", "Training a new tokenizer and model from scratch", "Running inference only with no adaptation"], a: 0, e: "LoRA and other PEFT methods train small adapter weights instead of all parameters, which cuts GPU memory and compute dramatically." },
  { d: 1, l: "m", q: "A city's video analytics platform must decode 200 camera streams and run object detection on each in real time. Which NVIDIA SDK is built for this streaming pipeline?", o: ["DeepStream", "Riva", "Merlin", "Parabricks"], a: 0, e: "DeepStream builds streaming video AI pipelines that use the GPU's hardware decoders plus TensorRT inference. It is part of Metropolis." },
  { d: 1, l: "m", q: "A genomics lab's whole-genome analysis pipeline takes about 30 hours per sample on CPUs. Which NVIDIA software is designed to accelerate this?", o: ["Clara Parabricks", "Isaac ROS", "Morpheus", "cuOpt"], a: 0, e: "Parabricks is the GPU-accelerated genomics suite in Clara and cuts secondary analysis from many hours to under an hour." },
  { d: 1, l: "m", q: "A weather research center needs FP64 double-precision performance for physics simulations and AI. Which GPU fits best?", o: ["A data center GPU with strong FP64, such as H100", "L4, because it has the lowest power draw", "A consumer GeForce card", "Jetson Orin, because it runs at the edge"], a: 0, e: "H100-class GPUs have high FP64 throughput for HPC. Inference-oriented GPUs such as L4 and L40S have limited FP64." },
  { d: 1, l: "m", q: "A data scientist prototypes on an RTX laptop and wants to move the same project to a DGX server or the cloud with a reproducible containerized environment. Which NVIDIA tool fits?", o: ["NVIDIA AI Workbench", "NVIDIA UFM", "NVIDIA DOCA", "NVIDIA Riva"], a: 0, e: "AI Workbench manages containerized projects so they move consistently between local and remote GPU systems." },
  { d: 1, l: "m", q: "An enterprise runs AI in production and needs long-term support branches, security patches and NVIDIA support for frameworks such as NIM, Triton and RAPIDS. What should it license?", o: ["NVIDIA AI Enterprise", "A GeForce driver subscription", "Only the free CUDA Toolkit", "NVIDIA Omniverse Create"], a: 0, e: "NVIDIA AI Enterprise adds production and long-term support branches, security fixes and enterprise support for the NVIDIA AI software stack." },
  { d: 1, l: "m", q: "A 3D vision model fits in one GPU's memory, but each training epoch takes 20 hours on a single GPU. The team has an 8-GPU server. Which approach is most appropriate?", o: ["Data parallelism: replicate the model on all 8 GPUs and split each batch, synchronizing gradients with NCCL", "Pipeline parallelism, because the model is too large for one GPU", "Run 8 copies with different random seeds and pick the best", "Use time-slicing to share one GPU across 8 jobs"], a: 0, e: "When the model fits on one GPU, data parallelism is the simplest way to cut training time. Model parallelism is for models that don't fit." },
  { d: 1, l: "m", q: "An autonomous vehicle company must train perception models on large fleets of driving data and validate them in simulated driving scenarios. Which NVIDIA platform covers this end to end?", o: ["NVIDIA DRIVE (with DRIVE Sim on Omniverse)", "NVIDIA Merlin", "NVIDIA Riva", "NVIDIA Clara"], a: 0, e: "DRIVE spans in-vehicle compute, AV software and simulation for validating autonomous driving." },
  { d: 1, l: "m", t: "multi", q: "A team is deciding whether its new workload will benefit from GPU acceleration. Which TWO characteristics suggest it will? (Select TWO.)", o: ["The same operation is applied to millions of independent data elements", "The core math is large matrix and vector operations", "Each step depends on the result of the previous step with heavy branching", "The workload mostly waits on user keyboard input", "The workload is a small single-threaded script that runs in milliseconds"], a: [0, 1], e: "GPUs win on data-parallel, math-heavy work. Serial, branchy, I/O-bound or tiny workloads gain little." },

  { d: 1, l: "h", q: "A team wants to serve a 70-billion-parameter LLM. Which statement about GPU memory for the model weights is correct?", o: ["In FP16 the weights alone need about 140 GB, so they must be split across at least two 80 GB GPUs or quantized", "In FP16 the weights need about 70 GB and fit easily on one 80 GB GPU with room for the KV cache", "Weight memory does not depend on numeric precision", "In FP8 the weights need about 280 GB"], a: 0, e: "Weight memory ≈ parameters × bytes per parameter: 70B × 2 bytes = 140 GB in FP16, and about 70 GB in FP8. The KV cache and activations also need memory, so tensor parallelism across GPUs is common." },
  { d: 1, l: "h", q: "A team wants to fully fine-tune (all weights) a 7-billion-parameter model with the Adam optimizer and mixed precision. A rule of thumb is about 16 bytes per parameter for weights, gradients and optimizer states. What should it expect?", o: ["About 112 GB before activations, more than a single 80 GB GPU, so it should shard across GPUs (FSDP/ZeRO) or use LoRA", "About 14 GB, so a single small GPU is enough", "About 7 GB, because only weights are stored", "Memory is unaffected by the choice of optimizer"], a: 0, e: "7B × 16 bytes ≈ 112 GB plus activations. Sharding optimizer states across GPUs or training only small LoRA adapters makes it fit." },
  { d: 1, l: "h", q: "Users of an LLM chatbot complain about a long wait before the first word appears when they paste long documents. Once text starts, it streams quickly. Which inference phase is the bottleneck?", o: ["Prefill: processing the long input prompt, which is compute-bound", "Decode: generating each new token, which is memory-bandwidth-bound", "Tokenizer download time", "Network latency between GPUs inside the server"], a: 0, e: "Time to first token is dominated by prefill, which processes all input tokens at once. Decode speed (inter-token latency) is a separate metric." },
  { d: 1, l: "h", q: "Moving LLM serving from H100 (80 GB HBM3) to H200 (141 GB HBM3e) increases token generation speed, even though peak compute is similar. What is the main reason?", o: ["Decode is limited by memory bandwidth and capacity, and H200 has more HBM capacity and higher bandwidth", "H200 runs at a much higher CPU clock", "H200 removes the need for a KV cache", "H200 uses a different instruction set that PyTorch prefers"], a: 0, e: "Each decode step reads the model weights and KV cache from memory. More bandwidth means faster tokens, and more capacity allows larger batches and longer contexts." },
  { d: 1, l: "h", q: "A chatbot has a p99 latency target of 300 ms. Raising the server batch size from 8 to 64 increased throughput 4x but pushed p99 latency to 900 ms. What is the best approach?", o: ["Choose the largest batch size (and queue delay) that still meets the 300 ms target, and add replicas to scale throughput", "Keep batch size 64 because throughput matters more than the SLA", "Disable batching and use one GPU", "Increase the batch size to 256 to finish requests faster"], a: 0, e: "Batching trades latency for throughput. Meet the SLA first, then scale out horizontally for more capacity." },
  { d: 1, l: "h", q: "A team on H100 GPUs wants the lowest-precision floating-point format that Hopper Tensor Cores natively accelerate for LLM inference. Which format is it?", o: ["FP8", "FP4", "FP64", "BF16"], a: 0, e: "Hopper introduced FP8 Tensor Core support. Native FP4 support arrived with Blackwell's second-generation Transformer Engine." },
  { d: 1, l: "h", q: "One GPU trains at 1,000 images per second. With 8 GPUs, the job reaches 6,400 images per second. What is the scaling efficiency?", o: ["80%", "64%", "125%", "8%"], a: 0, e: "Ideal throughput = 8 × 1,000 = 8,000 images/s. Efficiency = 6,400 ÷ 8,000 = 80%. The gap usually comes from communication overhead." },
  { d: 1, l: "h", q: "In a data pipeline, 20% of the runtime is serial CPU work that cannot be parallelized. The other 80% is moved to GPUs. What is the theoretical maximum overall speedup, even with infinitely fast GPUs?", o: ["5x", "80x", "20x", "Unlimited"], a: 0, e: "By Amdahl's law the serial part limits speedup: 1 ÷ 0.2 = 5x. Accelerated computing therefore also targets the serial bottlenecks." },
  { d: 1, l: "h", q: "A retailer's LLM assistant must use the exact current price and stock of 2 million products, which change hourly, and must speak in a distinctive brand tone. Which design fits best?", o: ["Use RAG for the live product facts, plus light fine-tuning (for example LoRA) or prompting for the brand tone", "Fine-tune the model on the catalog every hour", "Put the whole catalog in every prompt", "Pre-train a new model on the catalog once"], a: 0, e: "RAG handles fast-changing facts. Fine-tuning or prompt design handles style. Hourly fine-tuning would be slow, costly and still stale." },
  { d: 1, l: "h", q: "An LLM uses standard self-attention. The product team doubles the maximum context length from 32K to 64K tokens. Roughly how does attention compute per sequence change?", o: ["It roughly quadruples, because standard attention scales quadratically with sequence length", "It stays the same", "It roughly doubles", "It halves, because longer contexts are processed in parallel"], a: 0, e: "Each token attends to every other token, giving O(n²) cost. Doubling n gives about 4x the attention compute, and the KV cache memory doubles too." },
  { d: 1, l: "h", q: "A company serves a large LLM across many GPUs and nodes. It wants to separate the prefill and decode phases onto different GPUs, route requests to where KV cache already exists, and scale each phase independently. Which NVIDIA software is designed for this?", o: ["NVIDIA Dynamo", "NVIDIA DALI", "NVIDIA cuOpt", "NVIDIA Riva"], a: 0, e: "Dynamo is an open-source framework for distributed LLM inference, with disaggregated serving and KV-cache-aware routing, built to raise throughput at data center scale." },

  // ===== Domain 2: AI Infrastructure (40) =====
  { d: 2, l: "e", q: "Inside a single DGX H100, tensor-parallel training needs the 8 GPUs to exchange large tensors constantly. Which path carries this traffic?", o: ["NVLink through NVSwitch", "The out-of-band management network", "1 GbE in-band Ethernet", "USB"], a: 0, e: "NVSwitch connects all 8 GPUs all-to-all over NVLink at 900 GB/s per GPU on Hopper." },
  { d: 2, l: "e", q: "Two DGX systems in different racks must exchange gradients every training step. Which network carries this?", o: ["The compute fabric, InfiniBand or RoCE Ethernet, through ConnectX NICs", "The BMC out-of-band network", "The storage replication link", "NVLink cables between racks"], a: 0, e: "Between nodes, GPU traffic uses the RDMA compute fabric. NVLink only spans nodes in rack-scale systems such as NVL72." },
  { d: 2, l: "e", q: "A server hangs and its OS is unreachable over SSH. The admin needs to power-cycle it remotely and view its console. What is used?", o: ["The BMC over the out-of-band management network (IPMI/Redfish)", "The InfiniBand compute fabric", "nvidia-smi", "The Slurm controller"], a: 0, e: "The BMC runs independently of the host OS, which is why the out-of-band network exists." },
  { d: 2, l: "e", q: "A cloud provider wants to move virtual switching, firewalling and encryption off its host CPUs so more CPU cores can be sold to tenants. What should it add?", o: ["BlueField DPUs", "More GPUs", "Larger hard disks", "Faster BMCs"], a: 0, e: "DPUs offload and accelerate networking, storage and security infrastructure, freeing host CPU cores." },
  { d: 2, l: "e", q: "Data center A has a PUE of 1.2 and data center B has a PUE of 1.6. Which statement is correct?", o: ["A is more efficient: less non-IT overhead per watt delivered to IT equipment", "B is more efficient because its number is higher", "Both are equally efficient", "PUE measures GPU utilization, not facility efficiency"], a: 0, e: "PUE = total facility power ÷ IT power. Closer to 1.0 is better." },
  { d: 2, l: "e", q: "A server vendor builds an 8-GPU system on NVIDIA's validated GPU baseboard with NVLink and NVSwitch. What is that baseboard platform called?", o: ["HGX", "DGX Spark", "Jetson", "BlueField"], a: 0, e: "OEMs build on HGX. DGX is NVIDIA's own complete system." },
  { d: 2, l: "e", q: "A planned rack draws about 120 kW. Which cooling approach is required?", o: ["Liquid cooling, such as direct-to-chip", "Standard room air conditioning", "Opening the data center windows", "Adding perforated floor tiles only"], a: 0, e: "Air cooling tops out at roughly 30–40 kW per rack. Rack-scale systems such as GB200 NVL72 need liquid cooling." },
  { d: 2, l: "e", q: "When choosing GPU servers from several vendors, a buyer sees the label 'NVIDIA-Certified System.' What does it indicate?", o: ["NVIDIA has validated the server configuration for performance and compatibility with its GPUs, networking and software", "The server includes free GPUs", "The server cannot run Kubernetes", "The server is liquid-cooled only"], a: 0, e: "The NVIDIA-Certified Systems program tests partner servers so customers can deploy NVIDIA AI software with confidence." },
  { d: 2, l: "e", q: "A university lab needs 32 GPUs for a two-week hackathon and has no GPU hardware. Which option fits best?", o: ["Rent GPU instances from a cloud provider", "Buy a DGX SuperPOD", "Build a new data hall", "Use the lab's office desktops"], a: 0, e: "Short-term, bursty needs suit the cloud: no capital cost, no procurement lead time." },
  { d: 2, l: "e", q: "In a hot aisle / cold aisle layout, how should GPU servers be installed?", o: ["Intakes (fronts) face the cold aisle and exhausts (backs) face the hot aisle", "Intakes face the hot aisle", "Alternate directions in every rack", "Direction does not matter for GPU servers"], a: 0, e: "Servers draw cool air from the cold aisle and exhaust hot air into the contained hot aisle." },

  { d: 2, l: "m", q: "A colocation facility allows at most 20 kW per air-cooled rack. Each DGX H100 can draw up to about 10.2 kW. How many DGX H100 systems fit per rack at full power?", o: ["1", "2", "4", "8"], a: 0, e: "Two systems would need about 20.4 kW, which exceeds the 20 kW limit. Plan for maximum draw, not typical draw." },
  { d: 2, l: "m", q: "Training over a RoCE Ethernet fabric slows down unpredictably, and switch counters show packet drops during all-reduce bursts. What should be done?", o: ["Configure lossless Ethernet with PFC and ECN-based congestion control, or use an AI-tuned fabric such as Spectrum-X", "Disable RDMA and fall back to TCP", "Reduce MTU to 576 bytes", "Turn off all QoS on the switches"], a: 0, e: "RDMA over Ethernet performs poorly when packets drop. PFC prevents drops, and ECN tells senders to slow down before buffers fill." },
  { d: 2, l: "m", q: "After cabling a new InfiniBand fabric, the links show physical connectivity but every port stays in the 'Initializing' state and no traffic flows. What is the most likely cause?", o: ["No Subnet Manager is running on the fabric", "The GPUs need a BIOS update", "Slurm is not installed", "The BMC passwords are wrong"], a: 0, e: "The Subnet Manager (on a managed switch or UFM) assigns LIDs and routes and moves ports to Active. Without it, ports stay Initializing." },
  { d: 2, l: "m", q: "A 512-GPU job writes a 2 TB checkpoint every hour, and the GPUs sit idle until each write finishes. Which storage design best reduces this idle time?", o: ["A parallel file system with high aggregate write bandwidth, or asynchronous checkpointing to fast local NVMe that drains to shared storage", "A single NFS server on 10 GbE", "Writing checkpoints to object storage over the management network", "Disabling checkpoints entirely"], a: 0, e: "Checkpoints are large write bursts. High-throughput parallel storage and asynchronous checkpointing keep the GPUs busy." },
  { d: 2, l: "m", q: "A dataset of 300 million small JPEG files loads slowly even on fast storage, because of metadata overhead. What is the best improvement?", o: ["Pack the files into larger shards (for example tar or WebDataset), and cache them on local NVMe", "Convert each JPEG to a separate folder", "Move the files to a USB drive", "Reduce the number of GPUs"], a: 0, e: "Millions of tiny files stress file system metadata. Large sequential shards stream efficiently, and local caching cuts repeated reads." },
  { d: 2, l: "m", q: "What is the intended use of the local NVMe drives inside a DGX system?", o: ["Fast local cache or scratch space for datasets during training, not the durable system of record", "Long-term archival of all company data", "Storing the BMC firmware", "Replacing the shared parallel file system for all users"], a: 0, e: "Local NVMe speeds up repeated reads, but data there is not shared or protected. Durable data lives on shared storage." },
  { d: 2, l: "m", q: "A bank must keep customer data within its own country under regulation and plans to train models on it. Which deployment best addresses this?", o: ["On-premises infrastructure, or a cloud region in-country with strict data residency controls", "Any public cloud region with the lowest price", "Consumer GPU laptops for each data scientist", "A cloud region chosen at random for redundancy"], a: 0, e: "Data sovereignty and residency requirements often drive on-premises or sovereign cloud deployments." },
  { d: 2, l: "m", q: "An organization has standardized on Ethernet operations and tooling but needs network performance suitable for large-scale AI training. Which NVIDIA platform fits?", o: ["Spectrum-X: Spectrum-4 Ethernet switches with BlueField-3 SuperNICs, adaptive routing and congestion control", "Wi-Fi 7 access points", "A legacy 10 GbE switch stack", "NVLink cables between all racks"], a: 0, e: "Spectrum-X is NVIDIA's Ethernet platform built for AI, using RoCE with end-to-end congestion control." },
  { d: 2, l: "m", q: "In a DGX SuperPOD design, what is a scalable unit (SU)?", o: ["A standardized building block of DGX nodes plus its network and supporting components that is replicated to grow the system", "A single GPU", "A software license unit", "A cooling tower"], a: 0, e: "SuperPODs grow by adding scalable units, each with a validated design, so performance scales predictably." },
  { d: 2, l: "m", q: "In a rail-optimized fabric with 32 nodes of 8 GPUs, each leaf switch connects NIC number n from every node. Which traffic benefits most?", o: ["Collective operations between GPUs with the same local index across nodes, which stay one switch hop apart", "BMC management traffic", "User web browsing", "Storage replication between two arrays"], a: 0, e: "NCCL organizes collectives so that matching GPUs across nodes talk over their own rail, minimizing hops and congestion." },
  { d: 2, l: "m", q: "A compute fabric is designed with 2:1 oversubscription at the spine to save cost. Large training jobs then show poor all-reduce performance. What is the recommended design?", o: ["A non-blocking (1:1) fat-tree for the compute fabric", "Increase oversubscription to 4:1", "Route compute traffic over the management network", "Remove the spine switches"], a: 0, e: "AI collectives drive all links at once. Oversubscription creates bottlenecks, so compute fabrics are built non-blocking." },
  { d: 2, l: "m", q: "A retail chain wants to run AI video analytics on 30 camera streams in each store's back-room server, with limited power and cooling. Which GPU class fits?", o: ["A low-power inference GPU such as L4", "A GB200 NVL72 rack", "An 8-GPU DGX B200", "A GPU tuned for FP64 HPC"], a: 0, e: "L4 is a low-profile, roughly 72 W GPU built for video decode and efficient inference in standard servers." },
  { d: 2, l: "m", q: "A design firm wants one GPU type in its data center for both real-time 3D rendering of digital twins and AI inference. Which GPU fits best?", o: ["L40S", "Jetson Orin Nano", "A GPU without graphics engines, built only for training", "A CPU-only server"], a: 0, e: "L40S combines RT cores for graphics with Tensor Cores for AI, so it suits mixed visualization and AI workloads." },
  { d: 2, l: "m", q: "A cloud operator wants remote NVMe-over-Fabrics storage to appear to bare-metal tenants as a local NVMe drive, without installing special drivers on the tenant's OS. Which component enables this?", o: ["A BlueField DPU with storage emulation", "An NVSwitch", "A GPU with MIG enabled", "A Slurm prolog script"], a: 0, e: "BlueField can emulate NVMe devices to the host while connecting to remote storage, keeping infrastructure under the provider's control." },
  { d: 2, l: "m", q: "Why is the out-of-band management network usually kept physically separate from the compute and in-band networks?", o: ["So hardware management stays reachable and isolated even if the host OS or production networks fail or are compromised", "Because BMCs need 400 Gb/s bandwidth", "To carry GPU-to-GPU traffic", "Because InfiniBand cannot carry management traffic"], a: 0, e: "Separation improves availability and security. Attackers on production networks should not reach BMCs." },
  { d: 2, l: "m", q: "A company plans a liquid-cooled AI cluster. Which component transfers heat between the rack's coolant loop and the facility water system?", o: ["Coolant distribution unit (CDU)", "Power distribution unit (PDU)", "Subnet Manager", "Top-of-rack switch"], a: 0, e: "The CDU circulates coolant to the cold plates and exchanges heat with facility water, keeping the two loops separate." },
  { d: 2, l: "m", q: "64 GPUs each need to read training data at 500 MB/s to stay busy. What aggregate read throughput must storage deliver?", o: ["32 GB/s", "8 GB/s", "500 MB/s", "320 GB/s"], a: 0, e: "64 × 0.5 GB/s = 32 GB/s. Size storage for aggregate throughput, not just capacity." },
  { d: 2, l: "m", q: "During design review, an engineer asks why each GPU in the server should be paired with a NIC on the same PCIe switch. What is the main reason?", o: ["GPUDirect RDMA traffic takes the shortest path without crossing CPU sockets, which lowers latency and raises bandwidth", "It reduces the server's weight", "It is required for the BMC to work", "It allows GPUs to share one IP address"], a: 0, e: "Crossing the CPU interconnect between NUMA nodes hurts RDMA performance. Use nvidia-smi topo -m to check GPU–NIC affinity." },

  { d: 2, l: "h", q: "A large training job is dominated by all-reduce traffic. Which InfiniBand capability reduces the data each node sends by performing reductions inside the network switches?", o: ["SHARP in-network computing on Quantum switches", "Spanning Tree Protocol", "Jumbo frames", "IPMI over LAN"], a: 0, e: "SHARP aggregates data in the switches, lowering the volume and latency of collective operations." },
  { d: 2, l: "h", q: "H100 NVLink provides about 900 GB/s per GPU, while a PCIe Gen5 x16 link provides about 128 GB/s total. Roughly how much more GPU-to-GPU bandwidth does NVLink provide?", o: ["About 7x", "About 2x", "About 70x", "They are equal"], a: 0, e: "900 ÷ 128 ≈ 7. This is why tensor-parallel jobs keep GPUs within an NVLink domain." },
  { d: 2, l: "h", q: "A mixture-of-experts model needs constant all-to-all communication among 72 GPUs with the lowest possible latency. Which system design fits best?", o: ["GB200 NVL72, where 72 GPUs share one NVLink domain", "Nine separate DGX H100 nodes connected over 100 GbE", "72 L4 GPUs in separate servers", "One DGX H100 with time-slicing"], a: 0, e: "NVL72 extends NVLink and NVSwitch across the rack, so all 72 GPUs communicate at NVLink speed instead of going over the network." },
  { d: 2, l: "h", q: "A data hall has 1 MW of IT power available. Each DGX H100 draws up to 10.2 kW, and networking and storage add 10% on top of the compute load. About how many DGX H100 systems can be deployed?", o: ["About 89", "About 98", "About 120", "About 72"], a: 0, e: "Per system with overhead: 10.2 × 1.1 = 11.22 kW. 1,000 ÷ 11.22 ≈ 89 systems." },
  { d: 2, l: "h", q: "An AI cluster's IT load is 800 kW and the facility's PUE is 1.4. How much power goes to non-IT overhead such as cooling and power conversion?", o: ["320 kW", "1,120 kW", "560 kW", "80 kW"], a: 0, e: "Total facility power = 800 × 1.4 = 1,120 kW. Overhead = 1,120 − 800 = 320 kW." },
  { d: 2, l: "h", q: "An 8-GPU server costs about $400,000 to own and operate over 3 years ($133,000 per year). An equivalent cloud instance costs $40 per hour. Above roughly what utilization does owning become cheaper?", o: ["About 38% (about 3,300 hours per year)", "About 5%", "About 75%", "Cloud is always cheaper"], a: 0, e: "$133,000 ÷ $40 ≈ 3,333 hours, and 3,333 ÷ 8,760 hours ≈ 38%. Steady, high utilization favors on-premises." },
  { d: 2, l: "h", q: "A RoCE fabric relies only on Priority Flow Control (PFC). Under heavy load, operators see pause storms and congestion spreading to unrelated flows. What is the recommended improvement?", o: ["Add ECN-based end-to-end congestion control (for example DCQCN) so senders slow down before PFC pauses are triggered", "Disable PFC and accept packet loss", "Use larger hubs instead of switches", "Move all traffic to the BMC network"], a: 0, e: "PFC prevents drops but can cause head-of-line blocking and pause propagation. ECN signals congestion early so PFC acts only as a last resort." },
  { d: 2, l: "h", q: "A multi-tenant bare-metal GPU cloud gives tenants root access to their servers. The provider must still enforce network isolation and firewall policy that a tenant cannot tamper with. Where should these controls run?", o: ["On a BlueField DPU, isolated from the tenant-controlled host", "In iptables rules on the tenant's host OS", "In the tenant's application code", "In nvidia-smi settings"], a: 0, e: "A DPU forms a separate trust domain. Policies enforced there survive even if the host is fully controlled or compromised." },
  { d: 2, l: "h", q: "A company keeps a 2 PB training dataset on-premises and plans to burst training jobs to the cloud during peaks. What is the biggest practical challenge?", o: ["Data gravity: moving or syncing petabytes takes time and incurs transfer costs, so compute should run near the data or use a cached subset", "Cloud GPUs cannot run PyTorch", "On-premises storage cannot be read by GPUs", "Cloud providers prohibit AI training"], a: 0, e: "Large datasets are expensive and slow to move. Hybrid designs must plan data placement, caching and egress costs." },
  { d: 2, t: "multi", l: "h", q: "A new DGX cluster underperforms on multi-node training. Which TWO checks most directly validate that the compute fabric is delivering expected bandwidth? (Select TWO.)", o: ["Run NCCL tests (for example all_reduce_perf) across nodes and compare bus bandwidth with expected values", "Run InfiniBand perftest tools (for example ib_write_bw) between node pairs", "Check the BMC's fan speed settings only", "Measure the server's boot time", "Count the number of Slurm users"], a: [0, 1], e: "NCCL tests measure collective performance end to end, and perftest isolates point-to-point RDMA bandwidth to find bad links or NICs." },
  { d: 2, l: "h", q: "To cut cost, a team will train a model for three weeks on discounted cloud spot (preemptible) GPU instances that can be reclaimed with little notice. What must the training setup include to finish reliably?", o: ["Frequent checkpoints to durable storage and automatic restart or elastic resumption from the latest checkpoint", "A larger learning rate so training finishes before preemption", "Disabling checkpoints to save storage costs", "Pinning every job to a single fixed instance ID"], a: 0, e: "Spot capacity is cheap but can disappear at any time. Checkpoint-and-resume turns an interruption into a short delay instead of lost weeks." },
  { d: 2, l: "h", q: "An architect must choose GPUs for a new cluster that will primarily serve a 405-billion-parameter LLM with long contexts. Which factor most directly sets how many GPUs one model replica needs?", o: ["Total GPU memory (HBM capacity) needed for weights at the chosen precision plus the KV cache", "The CPU's clock speed", "The number of USB ports", "The rack's paint color"], a: 0, e: "Replica size is set by memory: weights (parameters × bytes) plus KV cache, which grows with context length and batch size. Bandwidth then drives speed." },

  // ===== Domain 3: AI Operations (22) =====
  { d: 3, l: "e", q: "An admin needs to see which processes are using GPU memory on one server right now. Which command is quickest?", o: ["nvidia-smi", "sinfo", "ibstat", "kubectl get nodes"], a: 0, e: "nvidia-smi lists per-GPU utilization, memory, temperature and the processes using each GPU." },
  { d: 3, l: "e", q: "A researcher wants a Slurm batch job to get 8 GPUs on one node. How is this requested?", o: ["Submit with sbatch and request GPUs as a generic resource, for example --gres=gpu:8 (or --gpus=8)", "Edit /etc/hosts", "Run nvidia-smi -pl 8", "Use kubectl scale --replicas=8"], a: 0, e: "Slurm schedules GPUs as GRES. The job script is submitted with sbatch, and srun launches tasks inside the allocation." },
  { d: 3, l: "e", q: "On a Kubernetes cluster with the NVIDIA GPU Operator, how does a pod request one GPU?", o: ["Set resources.limits to nvidia.com/gpu: 1 in the pod spec", "Add a label gpu=true to the namespace", "Mount /dev/nvidia0 as a ConfigMap", "Set the pod's CPU request to 1"], a: 0, e: "The NVIDIA device plugin advertises nvidia.com/gpu, and the scheduler places the pod on a node with a free GPU." },
  { d: 3, l: "e", q: "One GPU in a server consistently runs 15 °C hotter than the others and lowers its clocks. The others are normal. What should be checked first?", o: ["Airflow to that GPU: fans, blanking panels, blocked vents or cable obstructions", "The Slurm partition configuration", "The InfiniBand Subnet Manager", "The user's Python version"], a: 0, e: "A single hot GPU usually points to a local cooling problem. Thermal throttling reduces performance until it is fixed." },
  { d: 3, l: "e", q: "Several developers share older GPUs that do not support MIG for light notebook experiments. They don't need isolation and want to share each GPU. Which option fits?", o: ["GPU time-slicing", "MIG partitioning", "PCIe passthrough to one VM per GPU", "Buying one GPU per developer"], a: 0, e: "Time-slicing lets several workloads take turns on a GPU without hardware partitioning. It works on GPUs without MIG but gives no memory isolation." },

  { d: 3, l: "m", q: "An H100 80 GB GPU must host 7 equally sized inference services, each with hardware-isolated memory and compute. Which configuration fits?", o: ["Seven 1g.10gb MIG instances", "Seven time-sliced replicas", "One 7g.80gb MIG instance shared by all services", "Seven vGPU Q-series profiles"], a: 0, e: "A 1g.10gb MIG profile gives each instance one compute slice and about 10 GB of dedicated memory, and up to 7 fit on one H100 80 GB." },
  { d: 3, l: "m", q: "A Slurm node shows a GPU with rising ECC errors. Jobs currently running there should finish, but no new jobs should start on it. What should the admin do?", o: ["Set the node to DRAIN (for example with scontrol update ... State=DRAIN)", "Reboot the node immediately", "Delete the node from DNS", "Increase the node's priority weight"], a: 0, e: "DRAIN lets running jobs finish while the scheduler stops placing new work, so diagnostics or RMA can follow." },
  { d: 3, l: "m", q: "The same GPU problem occurs on a Kubernetes worker node. What is the equivalent of draining it?", o: ["kubectl cordon the node, then kubectl drain to evict workloads gracefully", "kubectl delete namespace default", "Scale every deployment to zero", "Restart the API server"], a: 0, e: "cordon marks the node unschedulable, and drain evicts its pods safely for maintenance." },
  { d: 3, l: "m", q: "Jobs on a large cluster occasionally fail minutes in because they land on nodes with faulty GPUs. What is the best preventive measure?", o: ["Run a quick DCGM health check (for example dcgmi diag at run level 1) in the scheduler's prolog and drain nodes that fail", "Ask users to check nodes manually before submitting", "Disable ECC on all GPUs", "Run nodes at maximum clocks"], a: 0, e: "Prolog or epilog health checks catch bad hardware automatically before a job wastes time on it." },
  { d: 3, l: "m", q: "A power budget forces an operator to limit how much power each GPU in a rack can draw. Which action does this?", o: ["Set a GPU power limit (for example nvidia-smi -pl, or through DCGM policies)", "Disable NVLink", "Remove half the memory modules", "Turn off persistence mode"], a: 0, e: "Power capping keeps GPUs within budget with a modest performance trade-off, and is often more efficient per watt." },
  { d: 3, l: "m", q: "A platform team wants GPU quotas per team, fractional GPUs for notebooks and idle GPUs lent automatically to other teams, on Kubernetes. What should it deploy?", o: ["NVIDIA Run:ai", "NVIDIA DeepStream", "NVIDIA Parabricks", "NVIDIA DOCA"], a: 0, e: "Run:ai adds AI workload scheduling, fair-share quotas, GPU fractioning and over-quota borrowing on top of Kubernetes." },
  { d: 3, l: "m", q: "An LLM inference service needs operational dashboards. Which set of metrics best reflects user experience and capacity?", o: ["Time to first token, inter-token latency, tokens per second and request queue time", "Disk defragmentation level and BIOS version", "Number of data scientists on the team", "Training loss and learning rate"], a: 0, e: "LLM serving SLOs focus on time to first token, streaming speed and throughput. Queue time shows when to scale out." },
  { d: 3, l: "m", q: "The system log shows 'Xid 79: GPU has fallen off the bus' on a node. What is the right response?", o: ["Drain the node, check PCIe seating, power and thermals, run diagnostics, and RMA the GPU if the error repeats", "Ignore it, because it is informational", "Increase the training batch size", "Reinstall the user's Python packages"], a: 0, e: "Xid 79 means the GPU stopped responding on PCIe, which indicates a hardware, power or thermal problem rather than an application bug." },
  { d: 3, l: "m", q: "An admin must provision consistent OS images, drivers and Slurm across 200 new GPU nodes and monitor them centrally. Which NVIDIA software fits?", o: ["NVIDIA Base Command Manager", "NVIDIA Riva", "NVIDIA Isaac Sim", "NVIDIA cuOpt"], a: 0, e: "Base Command Manager provisions, configures and monitors clusters and can deploy Slurm or Kubernetes." },
  { d: 3, l: "m", q: "Low-priority training jobs are often preempted by urgent jobs and lose hours of progress each time. What is the best mitigation?", o: ["Checkpoint training state regularly so preempted jobs resume from the last checkpoint", "Disable preemption permanently", "Give every job the highest priority", "Run all jobs on one GPU"], a: 0, e: "Frequent checkpoints make preemption cheap. The same practice protects against hardware failures and cloud spot interruptions." },

  { d: 3, l: "h", q: "nvidia-smi reports 100% GPU utilization, but the job is far slower than expected. DCGM profiling shows SM activity around 25% and low Tensor Core activity. What explains this?", o: ["nvidia-smi 'utilization' only means some kernel was running during the sample; DCGM profiling metrics show how much of the GPU is actually busy", "The GPU is fully saturated and needs replacing", "100% utilization guarantees optimal performance", "DCGM metrics are always wrong when nvidia-smi shows 100%"], a: 0, e: "GPU utilization is a time-based measure. Metrics such as SM activity, SM occupancy and tensor pipe activity show real efficiency, often revealing small kernels or data stalls." },
  { d: 3, l: "h", q: "Two pods share one GPU through time-slicing. One pod repeatedly crashes with out-of-memory errors whenever the other pod's workload grows. What is the right fix?", o: ["Use MIG so each workload gets dedicated, isolated GPU memory, or give each pod its own GPU", "Increase the number of time-slicing replicas", "Lower the pod's CPU request", "Disable ECC to free memory"], a: 0, e: "Time-slicing shares all GPU memory with no limits. MIG enforces hardware memory partitions, so one tenant cannot starve another." },
  { d: 3, l: "h", q: "A Kubernetes cluster uses the GPU Operator with the MIG 'mixed' strategy on H100 nodes. How does a pod request a specific MIG slice?", o: ["Request the MIG-specific resource, for example nvidia.com/mig-1g.10gb: 1", "Request nvidia.com/gpu: 0.14", "Add an environment variable MIG=7", "MIG slices cannot be used in Kubernetes"], a: 0, e: "With the mixed strategy, each MIG profile is advertised as its own resource type. With the single strategy, slices appear as nvidia.com/gpu." },
  { d: 3, l: "h", q: "A VMware-based private cloud must give several VMs GPU access for AI compute, with hardware isolation between tenants and support for live migration. Which approach fits best?", o: ["MIG-backed NVIDIA vGPU with compute (C-series) profiles, licensed through NVIDIA AI Enterprise", "Time-slicing inside a single shared VM", "PCIe passthrough of one GPU per VM, with no sharing", "Q-series virtual workstation profiles for AI training"], a: 0, e: "vGPU on top of MIG combines VM sharing with hardware isolation. C-series profiles target compute and AI, Q-series target graphics workstations. vGPU supports live migration." },
  { d: 3, l: "h", q: "An organization runs long multi-node MPI-style training jobs and also hosts many always-on inference microservices that autoscale. Which orchestration approach fits best?", o: ["Slurm (or an AI batch scheduler) for batch training, and Kubernetes for inference microservices, possibly on partitioned or shared infrastructure", "Kubernetes alone with no GPU device plugin", "Slurm alone for autoscaling web microservices", "Cron jobs on each node"], a: 0, e: "Slurm excels at batch, gang-scheduled HPC-style jobs. Kubernetes excels at long-running, autoscaling services. Many AI factories run both." },
  { d: 3, l: "h", q: "DCGM shows an H100 with a pending row remap after an uncorrectable memory error. What does this mean operationally?", o: ["The GPU has marked bad memory rows for replacement, and a GPU reset or reboot is needed to apply the remap; repeated failures mean RMA", "The GPU needs a new CUDA version", "ECC must be disabled to continue", "The NVLink bridge is missing"], a: 0, e: "A100/H100-class GPUs use row remapping instead of page retirement. Pending remaps apply at reset, and remap failures indicate hardware that needs replacing." },
  { d: 3, l: "h", q: "Several teams share a Slurm cluster, and one team keeps submitting thousands of jobs that monopolize the GPUs. What is the best scheduler-level fix?", o: ["Configure fair-share scheduling with per-account limits and QOS policies", "Ask the team to submit fewer jobs by email", "Shut the cluster down at night", "Give the busy team a separate login node"], a: 0, e: "Slurm's fair-share priority lowers the priority of heavy users, and QOS limits cap usage per account, partition or job." }
]);
